import TestimonialsSectionV1 from "./components/testimonials-section-v1"

export default function Page() {
  return <TestimonialsSectionV1 />
}

import TestimonialsCarousel from "./testimonials-carousel"
import { sectionMeta, testimonials } from "../lib/testimonials-content"
import "../styles/testimonials-section-v1.css"

export default function TestimonialsSectionV1() {
  return (
    <section className="py-16 md:py-20 lg:py-24">
      <div className="mx-auto max-w-6xl px-4">
        <h2 className="mb-10 text-3xl font-medium tracking-tight md:mb-12">
          {sectionMeta.title}
        </h2>
        <TestimonialsCarousel testimonials={testimonials} />
      </div>
    </section>
  )
}

"use client"

import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  useCarousel,
} from "@/components/ui/carousel"

import type { Testimonial } from "../lib/testimonials-content"
import TestimonialCard from "./testimonial-card"

function CarouselNav() {
  const { scrollPrev, scrollNext, canScrollPrev, canScrollNext } = useCarousel()

  return (
    <div className="flex shrink-0 gap-2">
      <Button
        type="button"
        variant="outline"
        size="icon-sm"
        className="size-9 rounded-full border-border bg-background text-muted-foreground hover:bg-muted hover:text-foreground disabled:opacity-40"
        disabled={!canScrollPrev}
        aria-label="Previous testimonial"
        onClick={scrollPrev}
      >
        <ChevronLeftIcon />
      </Button>
      <Button
        type="button"
        variant="outline"
        size="icon-sm"
        className="size-9 rounded-full border-border bg-background text-muted-foreground hover:bg-muted hover:text-foreground disabled:opacity-40"
        disabled={!canScrollNext}
        aria-label="Next testimonial"
        onClick={scrollNext}
      >
        <ChevronRightIcon />
      </Button>
    </div>
  )
}

export default function TestimonialsCarousel({
  testimonials,
}: {
  testimonials: Testimonial[]
}) {
  return (
    <Carousel opts={{ align: "start", loop: false }} className="w-full">
      <CarouselContent className="-ml-6 items-stretch md:-ml-8">
        {testimonials.map((testimonial) => (
          <CarouselItem
            key={testimonial.id}
            className="flex basis-full pl-6 md:basis-1/2 md:pl-8"
          >
            <TestimonialCard testimonial={testimonial} />
          </CarouselItem>
        ))}
      </CarouselContent>
      <div className="mt-8">
        <CarouselNav />
      </div>
    </Carousel>
  )
}

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"

import type { Testimonial } from "../lib/testimonials-content"

export default function TestimonialCard({
  testimonial,
}: {
  testimonial: Testimonial
}) {
  return (
    <article className="ts1-card relative flex h-full min-h-48 w-full flex-col pl-6 md:pl-8">
      <blockquote className="text-base leading-relaxed text-foreground">
        {testimonial.quote}
      </blockquote>
      <footer className="ts1-card-footer mt-auto flex items-center gap-4 pt-8">
        <Avatar size="lg" className="overflow-hidden">
          <AvatarImage
            src={testimonial.avatarSrc}
            alt={testimonial.name}
            className="object-cover object-center"
          />
          <AvatarFallback>{testimonial.initials}</AvatarFallback>
        </Avatar>
        <div>
          <p className="text-sm font-medium">{testimonial.name}</p>
          <p className="text-sm text-muted-foreground">
            {testimonial.role}, {testimonial.company}
          </p>
        </div>
      </footer>
    </article>
  )
}

.ts1-card::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--border);
  z-index: 0;
}

.ts1-card-footer::after {
  content: "";
  position: absolute;
  left: calc(-1.5rem - 1px);
  bottom: 0;
  width: 3px;
  height: 2.5rem;
  background: var(--foreground);
  z-index: 1;
}

@media (min-width: 768px) {
  .ts1-card-footer::after {
    left: calc(-2rem - 1px);
  }
}
